import prismaMock from '../prisma-mock';
import {
  deleteComment,
  favoriteArticle,
  getArticles,
  getCommentsByArticle,
  unfavoriteArticle,
  updateComment,
} from '../../app/routes/article/article.service';

describe('ArticleService', () => {
  describe('deleteComment', () => {
    test('should throw an error ', () => {
      // Given
      const id = 123;
      const idUser = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      expect(deleteComment(id, idUser)).rejects.toThrowError();
    });

    test('should set deletedAt and keep the row instead of deleting it', async () => {
      // Given
      const id = 123;
      const userId = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({
        author: { id: userId, username: 'RealWorld' },
      });

      await deleteComment(id, userId);

      // Then
      expect(prismaMock.comment.delete).not.toHaveBeenCalled();
      expect(prismaMock.comment.update).toHaveBeenCalledWith({
        where: { id },
        data: { deletedAt: expect.any(Date) },
      });
    });

    test('should only look for live comments owned by the caller', async () => {
      // Given
      const id = 123;
      const userId = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(deleteComment(id, userId)).rejects.toMatchObject({ errorCode: 404 });
      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ id, deletedAt: null, author: { id: userId } }),
        }),
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });
  });

  describe('getCommentsByArticle', () => {
    test('should leave out soft-deleted comments', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';

      // When
      // @ts-ignore
      prismaMock.article.findUnique.mockResolvedValue({ comments: [] });

      await getCommentsByArticle(slug);

      // Then
      expect(prismaMock.article.findUnique).toHaveBeenCalledWith(
        expect.objectContaining({
          include: expect.objectContaining({
            comments: expect.objectContaining({
              where: expect.objectContaining({ deletedAt: null }),
            }),
          }),
        }),
      );
    });
  });

  describe('favoriteArticle', () => {
    test('should return the favorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      // @ts-ignore
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(favoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(favoriteArticle(slug, id)).rejects.toThrowError();
    });
  });
  describe('unfavoriteArticle', () => {
    test('should return the unfavorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(unfavoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(unfavoriteArticle(slug, id)).rejects.toThrowError();
    });
  });

  describe('updateComment', () => {
    const slug = 'How-to-train-your-dragon';
    const commentId = 123;
    const userId = 456;

    const mockedUpdatedComment = (createdAt: Date, body: string) => ({
      id: commentId,
      createdAt,
      updatedAt: createdAt,
      editedAt: new Date(),
      body,
      authorId: userId,
      articleId: 789,
      author: {
        username: 'RealWorld',
        bio: null,
        image: null,
        followedBy: [],
      },
    });

    test('should throw 422 when the new body is empty', async () => {
      // Given
      const body = '';

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(updateComment(body, slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 422,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw 404 when the comment is not found for this author', async () => {
      // Given
      const body = 'Edited text';

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(updateComment(body, slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 404,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw 403 when the comment is older than 30 minutes', async () => {
      // Given
      const body = 'Edited text';
      const createdAt = new Date(Date.now() - 31 * 60 * 1000);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });

      // Then
      await expect(updateComment(body, slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 403,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should update the body and set editedAt when within 30 minutes', async () => {
      // Given
      const body = 'Edited text';
      const createdAt = new Date(Date.now() - 29 * 60 * 1000);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment(createdAt, body));

      // Then
      const result = await updateComment(body, slug, commentId, userId);

      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: expect.objectContaining({ body, editedAt: expect.any(Date) }),
        }),
      );
      expect(result).toMatchObject({ id: commentId, body, editedAt: expect.any(Date) });
    });
  });

  describe('getArticles', () => {
    beforeEach(() => {
      // @ts-ignore
      prismaMock.article.count.mockResolvedValue(0);
      // @ts-ignore
      prismaMock.article.findMany.mockResolvedValue([]);
    });

    test('should cap take at 50 when the limit is above 50', async () => {
      // Given
      const query = { limit: '500' };

      // When
      await getArticles(query);

      // Then
      expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
        expect.objectContaining({ take: 50 }),
      );
    });

    test('should cap take at 50 when the limit is exactly 51', async () => {
      // Given
      const query = { limit: '51' };

      // When
      await getArticles(query);

      // Then
      expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
        expect.objectContaining({ take: 50 }),
      );
    });

    test('should keep the limit when it is 50 or below', async () => {
      // Given
      const query = { limit: '20' };

      // When
      await getArticles(query);

      // Then
      expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
        expect.objectContaining({ take: 20 }),
      );
    });

    test('should allow a limit of exactly 50', async () => {
      // Given
      const query = { limit: '50' };

      // When
      await getArticles(query);

      // Then
      expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
        expect.objectContaining({ take: 50 }),
      );
    });

    test('should default take to 10 when no limit is given', async () => {
      // Given
      const query = {};

      // When
      await getArticles(query);

      // Then
      expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
        expect.objectContaining({ take: 10 }),
      );
    });
  });
});
